choose.when:
/* 심사자(01) - CSPD001TM (심사마스터테이블)의 AI_INSPE_ENO (심사자직원번호) */
AND A.AI_INSPE_ENO = #{schUserNo}
AND A.AI_INPT_ACVT_CD IN ('80', '90', '150')

/* 결재자(02) - CSPD001TM (심사마스터테이블)의 AI_INPT_SNPE_ENO (담당결재자직원번호) */
AND ((A.AI_INPT_SNPE_ENO = #{schUserNo} AND A.AI_INPT_ACVT_CD IN ('100','130')) 
	 OR (A.QLAS_SNPE_ENO = #{schUserNo} AND A.AI_INPT_QLAS_ACVT_CD IN ('120','130') AND QLAS_PRG_YN = 'Y'))

/* QA(03) - CSPD001TM (심사마스터테이블)의 QLAS_CRPE_ENO (품질보증담당자직원번호) */
AND A.QLAS_CRPE_ENO = #{schUserNo}
AND A.AI_INPT_ACVT_CD IN ('140', '160') AND A.AI_INPT_QLAS_ACVT_CD = '110'

mapper.update:
/* 업무재할당 관리 (7080) */
/* AdminReTaskMapper.updateReTask */
/* 업무재할당 처리 */
DECLARE
	V_CHK							NUMBER(3);										/* 권한 인수인계 가능여부, 1 - 가능, 0 - 불가 */
	V_INPT_MST_SRNO					CSPD001TM.INPT_MST_SRNO%TYPE;					/* 업무 인수인계할 심사번호 */
	V_INPT_USER_ENO					CSPD101TI.AI_INPT_USER_ENO%TYPE;				/* 인수자 직원 번호 */
	V_INPT_USER_AUT_CD				CSPD101TI.AI_INPT_AUT_CD%TYPE;				/* 인수자 직원 권한코드 */
	V_QLAS_PRG_YN					CSPD001TM.QLAS_PRG_YN%TYPE;				/* 업무구분 코드 */
	V_OLD_INPT_USER_ENO				CSPD101TI.AI_INPT_USER_ENO%TYPE;				/* 인계자 직원 번호 */
	V_OLD_INPT_USER_AUT_CD			CSPD101TI.AI_INPT_AUT_CD%TYPE;				/* 인계자 직원 권한코드 */
BEGIN
/*
[참조사항]
* 심사업무 마스터 테이블의 권한별 담당직원 컬럼정보
- CSPD001TM.AI_INSPE_ENO	: 심사자직원번호
- CSPD001TM.AI_APPV_ENO		: 담당결재자직원번호
- CSPD001TM.QLAS_CRPE_ENO	: 품질보증담당자직원번호
* 사용자 권한 코드
- 01 : S1 (심사자)
- 02 : S2 (결재자)
- 03 : QA
- 04 : 일반
*/

	/* 변수 초기화 */
	V_CHK							:= 1;
	V_INPT_MST_SRNO					:= #{inptMstSrno};
	V_INPT_USER_ENO					:= #{inptBizAlctCrpeEno};
	V_OLD_INPT_USER_ENO				:= #{oldUserEno};
	V_QLAS_PRG_YN					:= #{qlasPrgYn};	
	/* 인계자 사용자 정보 설정 - 권한코드 */
	SELECT AI_INPT_AUT_CD
	INTO V_OLD_INPT_USER_AUT_CD
	FROM CSPD101TI
	WHERE AI_INPT_USER_ENO = V_OLD_INPT_USER_ENO;

	/* 인수자 사용자 정보 설정 - 권한코드 */
	SELECT AI_INPT_AUT_CD
	INTO V_INPT_USER_AUT_CD
	FROM CSPD101TI
	WHERE AI_INPT_USER_ENO = V_INPT_USER_ENO;

	/* 인수자와 인계자가 같으면, 인수인계 불가 */
	IF V_CHK = 1 AND V_INPT_USER_ENO = V_OLD_INPT_USER_ENO THEN
		V_CHK := 0;
	END IF;

	/* 인수자와 인계자의 권한이 다르면, 작업 인수인계 불가 */
	IF V_CHK = 1 AND V_INPT_USER_AUT_CD != V_OLD_INPT_USER_AUT_CD THEN
		V_CHK := 0;
	END IF;

	/* 일반사용자는, 작업 인수인계 불가 */
	IF V_CHK = 1 AND V_INPT_USER_AUT_CD = '04' OR V_OLD_INPT_USER_AUT_CD = '04' THEN
		V_CHK := 0;
	END IF;

	/* 권한별 심사업무 업데이트 */
	IF V_CHK = 1 THEN

		/* 심사자 업무 인수인계 처리 */
		IF V_INPT_USER_AUT_CD = '01' THEN
			UPDATE CSPD001TM SET
				AI_INSPE_ENO = #{inptBizAlctCrpeEno}
				, AI_INPT_SNPE_ENO = (
										SELECT AI_INPT_SNPE_ENO 
										  FROM CSPD101TI
										 WHERE AI_INPT_USER_ID = #{inptBizAlctCrpeEno}
				                      )
				, LST_DB_CHG_ID = #{lstDbChgId}
				, LST_DB_CHG_DTM = 
				, TRN_LOG_SRNO = #{trnLogSrno}
			WHERE INPT_MST_SRNO = #{inptMstSrno};
		END IF;

		/* 결재자 업무 인수인계 처리 */
		IF V_INPT_USER_AUT_CD = '02' THEN
			IF V_QLAS_PRG_YN = 'Y' THEN
				UPDATE CSPD001TM SET
					QLAS_SNPE_ENO = #{inptBizAlctCrpeEno}
					, LST_DB_CHG_ID = #{lstDbChgId}
					, LST_DB_CHG_DTM = 
					, TRN_LOG_SRNO = #{trnLogSrno}
				WHERE INPT_MST_SRNO = #{inptMstSrno};
			END IF;

			IF V_QLAS_PRG_YN ='N' THEN
				UPDATE CSPD001TM SET
					AI_INPT_SNPE_ENO = #{inptBizAlctCrpeEno}
					, LST_DB_CHG_ID = #{lstDbChgId}
					, LST_DB_CHG_DTM = 
					, TRN_LOG_SRNO = #{trnLogSrno}
				WHERE INPT_MST_SRNO = #{inptMstSrno};
			END IF;	
		END IF;

		/* QA 업무 인수인계 처리 */
		IF V_INPT_USER_AUT_CD = '03' THEN
			UPDATE CSPD001TM SET
				QLAS_CRPE_ENO = #{inptBizAlctCrpeEno}
				, QLAS_SNPE_ENO = (
										SELECT AI_INPT_SNPE_ENO 
										  FROM CSPD101TI
										 WHERE AI_INPT_USER_ID = #{inptBizAlctCrpeEno}
				                      )
				, LST_DB_CHG_ID = #{lstDbChgId}
				, LST_DB_CHG_DTM = 
				, TRN_LOG_SRNO = #{trnLogSrno}
			WHERE INPT_MST_SRNO = #{inptMstSrno};
		END IF;

	END IF;

EXCEPTION
	WHEN NO_DATA_FOUND THEN NULL;
END;

mapper.delete:
DELETE FROM CSPD008TH 
WHERE INPT_MST_SRNO = #{inptMstSrno} 
	AND AI_INPT_BIZ_DSCD = '3'
	AND AI_INPT_PRG_SRNO = (
		SELECT MAX(AI_INPT_PRG_SRNO)FROM CSPD008TH 
		WHERE INPT_MST_SRNO = #{inptMstSrno} 
		AND AI_INPT_BIZ_DSCD = '3'
	)

mapper.update:
UPDATE CSPD001TM SET QLAS_PRG_YN = NULL
	, AI_INPT_QLAS_APPV_STCD = NULL
	, AI_INPT_QLAS_PROS_CD = NULL
	, AI_INPT_QLAS_ACVT_CD = NULL
	, QLAS_ALOC_DT = NULL
	, TRN_LOG_SRNO = #{trnLogSrno}
	, LST_DB_CHG_ID = #{lstDbChgId}
	, LST_DB_CHG_DTM = (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL)
WHERE INPT_MST_SRNO = #{inptMstSrno}
